def safe_order(available, alloc, need):
    work, done, order = list(available), set(), []
    while len(done) < len(alloc):
        for team in sorted(alloc):
            if team not in done and all(n <= w for n, w in zip(need[team], work)):
                work = [w + a for w, a in zip(work, alloc[team])]   # team finishes, returns all
                done.add(team)
                order.append(team)
                break
        else:
            return None                                             # nobody can finish
    return order


available = [2, 1]                               # free: lab PCs, projectors
alloc = {"T1": [1, 0], "T2": [2, 1], "T3": [1, 1]}
maximum = {"T1": [3, 1], "T2": [3, 1], "T3": [4, 2]}
need = {t: [m - a for m, a in zip(maximum[t], alloc[t])] for t in alloc}
print("Abhi safe?", " ".join(safe_order(available, alloc, need)))

for ask in ([1, 1], [2, 1]):
    avail2 = [a - r for a, r in zip(available, ask)]
    alloc2 = dict(alloc, T3=[a + r for a, r in zip(alloc["T3"], ask)])
    need2 = dict(need, T3=[n - r for n, r in zip(need["T3"], ask)])
    order = safe_order(avail2, alloc2, need2)
    print(f"T3 maange {tuple(ask)}:", f"de do (safe order {' '.join(order)})" if order else "ruko (koi safe order nahi)")
